document.addEventListener("DOMContentLoaded",()=>{const e="section .container-fluid",t=document.querySelectorAll(e);if(0===t.length)return;t.forEach(e=>e.classList.add("reveal"));const n={root:null,threshold:.15},r=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("visible"),t.unobserve(e.target))})},n);t.forEach(e=>r.observe(e))});